// Historical context; relief probabilities remain game rules.
public static class DiplomaticChronicles
{
    public sealed class Profile { public string Religion; public bool Orthodox; public string[] Paragraphs; public Profile(string religion,bool orthodox,string[] paragraphs) {Religion=religion;Orthodox=orthodox;Paragraphs=paragraphs;} }
    public static readonly Profile[] All={
        new Profile("Catholic",false,new[]{"Hungary holds the middle Danube, where royal towns and fortified river crossings face the Ottoman advance. Its great captains have fought the Sultan's armies before; the defeats at Varna and Kosovo remain fresh wounds.","The crown belongs to the Latin Church. Bishops, magnates and military households can all answer a call to defend Christendom, although they seldom agree on who should pay for it.","A surviving Constantinople would occupy Ottoman armies far from Hungary's southern frontier. Yet another distant expedition risks men needed at home. Your envoy must offer a strategic opportunity as well as a Christian appeal."}),
        new Profile("Catholic",false,new[]{"Venice governs from a lagoon, but her fortunes sail across the eastern sea. Merchants, island governors and naval officers watch the straits through which their grain and cargoes must pass.","The republic worships in the Latin rite. Her colonies include many Orthodox Christians, and her Senate weighs commercial privilege alongside religious obligation.","Venetians already share the City's danger. Relief would defend their people and trading routes, but raising a fleet takes orders, money and time. The Senate must be persuaded that Constantinople can hold until its ships arrive."}),
        new Profile("Catholic",false,new[]{"Genoa's merchants reach from the Ligurian coast to the ports of the Black Sea. Powerful families and colonial officers pursue interests of their own; an agreement with the republic does not settle every quarrel in Galata.","Genoa is Catholic, while her trading settlements live among Greeks, Armenians and other communities. Shared faith with Rome binds her less tightly than a single banner might suggest.","Genoese volunteers can defend Constantinople while their countrymen negotiate with the Sultan. Secure passage, colonial possessions and the fate of Galata all matter. A policy that wins one Genoese captain may alarm another."}),
        new Profile("Catholic",false,new[]{"Pope Nicholas V rules a territorial state in Italy and speaks to princes far beyond it. Rome possesses money, envoys and spiritual authority; the armies of Christendom remain in other hands.","The papacy seeks the fulfilment of the Union of Florence. Communion with Rome gives an appeal for aid greater force, while the City's opposition to union troubles its advocates.","The Pope can send funds and ships and urge rulers to act. He cannot make every king abandon his own war. A successful embassy must turn declarations of Christian duty into supplies aboard vessels already preparing to sail."}),
        new Profile("Catholic",false,new[]{"Skanderbeg's Albanian resistance holds mountain strongholds against Ottoman power. Its strength rests on local knowledge, fighting households and alliances that must repeatedly be renewed.","Skanderbeg's diplomacy looks towards Catholic Italy. Albania itself contains Catholic, Orthodox and Muslim communities; allegiance and survival cut across these divisions.","The City and the Albanian lords face the same expanding enemy. An Ottoman reverse here would help them, but every experienced fighter sent abroad is absent from a vulnerable homeland. Even a small contingent would be a costly commitment."}),
        new Profile("Catholic",false,new[]{"The Hospitallers began as a brotherhood caring for pilgrims in Jerusalem, then acquired a military role in the crusader states. After losing their foothold in the Holy Land, they established themselves on Rhodes in the early fourteenth century. The fortified island now sits astride the eastern sea routes. Their ships and garrisons give a small order a reach far beyond its numbers.","The brothers are a Catholic military order under religious vows, sustained by a wider network of European houses and estates. Their identity combines armed service with the care of the sick; a hospital and a fortress belong to the same institution. They govern an island with a substantial Greek Orthodox population, whose labour and cooperation sustain the fortress.","Constantinople is close enough for Rhodian ships to matter. The Order must also guard its own island and sea lanes. Your appeal competes with the Grand Master's duty to keep Rhodes ready for the next attack."}),
        new Profile("Catholic",false,new[]{"Alfonso rules Naples as well as the Crown of Aragon, including Sicily and Sardinia. These are distinct realms with their own institutions, joined by one ruler and his ambitions. His southern Italian court can draw on ports, soldiers and money across the western Mediterranean.","The monarchy is Catholic. Crusading language sits beside dynastic claims and the ambitions of a court that remembers older Latin enterprises in Greek lands. Shared sovereignty does not make every local interest identical.","Your dealings with Alfonso are recorded through the Neapolitan embassy. Aragonese, Sicilian and Sardinian possessions lead to the same relationship and the same promised expedition. Winning a second audience in another possession cannot produce a second copy of that commitment."}),
        new Profile("Catholic",false,new[]{"Frederick III bears the imperial title, but the German lands contain princes, bishops and cities with treasuries and armies of their own. An imperial appeal must travel through many councils before it becomes a marching column.","The Emperor and most of these rulers belong to the Latin Church. Religious divisions in the wider imperial world, especially over Bohemia, complicate any claim to effortless Christian unity.","Constantinople's cause can command sympathy and prestige. Distance, divided authority and the cost of assembling an expedition make prompt relief difficult. A modest force or a purse of money is easier to secure than the whole strength of the Empire."}),
        new Profile("Catholic",false,new[]{"Charles VII's France is recovering land and authority after generations of war with England. Its captains have experience, but its towns and countryside have paid dearly for their victories.","France is Catholic, with a proud crown and an influential clergy. Royal policy guards the king's authority even when Rome calls for common action.","A crusading enterprise could bring honour, but the eastern sea lies far beyond the king's immediate concerns. Ships, passage and provisioning must all be arranged. A French promise is valuable only if the City can survive the long journey that follows."}),
        new Profile("Catholic court",false,new[]{"The duchy of Athens survives under the Florentine Acciaioli house, ruling from the ancient city and its fortified heights. Its small court lives among stronger neighbours and unsettled succession politics.","The ruling dynasty is Catholic; much of the population follows the Orthodox Church. A ducal decision therefore speaks for a government rather than a single religious community.","Ottoman pressure leaves Athens little freedom of action, and its relations with the Roman rulers of the Morea have also been hostile. Fear of the Sultan might inspire secret assistance, but it can just as easily compel refusal."}),
        new Profile("Orthodox",true,new[]{"Georgia stretches across mountain valleys and routes between the Black Sea and the lands beyond the Caucasus. King George VIII must contend with powerful regional lords as well as enemies on his borders.","The Georgian Church is Orthodox, with its own language, traditions and ancient monasteries. Communion with the Greeks gives your embassy a language of shared sacred duty.","Constantinople's survival would preserve an important Christian power on the western sea. Yet Georgia's own divisions and the long journey limit what its king can promise. Volunteers and supplies are more plausible than an army stripped from its frontier."}),
        new Profile("Orthodox",true,new[]{"Trebizond clings to the southern shore of the Black Sea, where the Grand Komnenoi maintain an imperial court amid mountains, ports and caravan routes. Its wealth exceeds the breadth of its territory.","Its dynasty and Church are Orthodox. Imperial ancestry and Greek learning connect it to Constantinople, despite centuries of separate rule and competing claims.","The fall of your City would leave Trebizond more exposed. Its merchants can send provisions and its court can offer men, but the route runs through seas increasingly threatened by Ottoman power. Sympathy does not remove that danger."}),
        new Profile("Catholic court",false,new[]{"John II's Cyprus is a Lusignan kingdom whose ports link the Levant with the Aegean. Genoese power at Famagusta and tribute owed to Egypt weigh heavily on the crown.","The royal house is Catholic, while most islanders are Orthodox. Queen Helena Palaiologina brings a close connection to the Greek imperial world and its religious life.","These ties give Constantinople friends at court. Money, ships and political freedom remain scarce. Aid must be assembled without provoking the powers already pressing upon the island."}),
        new Profile("Catholic dynasty · Orthodox Ruthenian lands",false,new[]{"Casimir rules as Grand Duke of Lithuania and King of Poland. The Vytis and the White Eagle stand for two lands with their own laws, councils and powerful lords. For Constantinople, the nearer concern is Lithuania's southern frontier: its Ruthenian lands and the routes down the Dnieper draw its attention towards the Black Sea, Crimea and the steppe.","The dynasty is Catholic, as is the Polish crown, while many of Lithuania's Ruthenian subjects are Orthodox. An imperial envoy can appeal to both the defence of Christendom and the interests of frontier lords who watch the balance of power around the Black Sea. Casimir must also reckon with disputes nearer the Baltic and with magnates reluctant to pay for a distant expedition.","His elder brother, Władysław, fell fighting the Ottomans at Varna in 1444. Another appeal from a threatened Christian city therefore reaches a court that knows the cost of such a campaign. Whether that memory encourages aid or counsels caution is for your embassy to discover. The Lithuanian frontier gives Casimir a particular interest in the Black Sea, while obligations in both his realms weigh upon his answer."}),
        new Profile("Catholic",false,new[]{"The Teutonic Order holds a fortified state in Prussia, built around castles, estates and Baltic commerce. Its towns and nobles increasingly challenge the burdens imposed by their masters.","The brothers are a Catholic military order. Their old crusading identity has become entangled with disputes against Christian neighbours and subjects.","An eastern expedition offers a return to a celebrated religious purpose, but the Order cannot lightly weaken its troubled homeland. Money and a small body of volunteers are more conceivable than the departure of its principal army."}),
        new Profile("Catholic",false,new[]{"Henry VI's England is burdened by the long French war and rivalries among great households. Resources raised for distant victories have brought disappointments home.","The English crown and Church are Catholic. Pilgrimage, crusading memory and devotion can make the City's appeal intelligible even at this distance.","English archers would be welcome on your walls. Getting them here requires money, ships and passage across several seas, while the crown faces urgent demands of its own. An expedition would depend as much on determined patrons as on royal sympathy."}),
        new Profile("Muslim",false,new[]{"Ibrahim Bey rules Karaman, an Anatolian principality centred on Konya and Larende. Its dynasty competes with the Ottomans for influence, routes and towns across central and southern Anatolia. A powerful Sultan threatens its room to manoeuvre even when the two courts are formally at peace.","Karaman is a Muslim power with its own rulers, religious foundations and political ambitions. Shared faith with the Ottomans does not erase their rivalry. Its merchants trade with Christian as well as Muslim neighbours; grain, horses and other goods give diplomacy practical substance.","Your envoys can appeal to Ibrahim's interest in preventing an Ottoman victory from making Mehmed stronger. Open intervention would be dangerous; discreet money and provisions might serve his purposes at less risk to his own lands."}),
        new Profile("Muslim",false,new[]{"The eastern marches are divided among rival Turkmen confederations. The Aq Qoyunlu, or White Sheep, hold Amid and the upper Tigris; the Qara Qoyunlu, or Black Sheep, rule from Tabriz across Azerbaijan and much of Iraq and western Iran. Their strength rests on mounted tribal followings, fortified towns and the revenues of settled lands. Neither house speaks for the other.","Both ruling houses are Muslim. Dynastic rivalry matters at least as much as religious solidarity, while the Aq Qoyunlu have long-standing family connections with the emperors of Trebizond. An envoy who understands these ties may find a hearing where an appeal to shared faith would fail.","Your present embassy approaches the Aq Qoyunlu through Trebizond. Discreet funds and provisions are possible; command of both confederations' armies is not. Their own struggles can make Constantinople useful to them, but a promise of relief does not commit the eastern lords to war."}),
        new Profile("Orthodox",true,new[]{"Wallachia guards approaches to the lower Danube. Its court must weigh every promise against armies that could cross the river before help arrived from elsewhere.","An imperial embassy appeals to shared faith and a common danger, but a ruler whose throne is insecure needs more than courage. Church Union affects the hearing you receive; it does not make every other interest disappear.","Your first appeal seeks a modest body of soldiers and supplies. A resident envoy can build the confidence needed for a separate war commitment, putting pressure on Ottoman deliveries from Moesia."}),
        new Profile("Orthodox",true,new[]{"Moldavia lies between stronger neighbours and the routes leading towards the Black Sea. Soldiers promised abroad must be soldiers the court can afford to spare at home.","Its Orthodox rulers can hear Constantinople's appeal as a family of faith pleading for its greatest city. They will still ask who protects their own lands while their men are absent.","Soldiers and supplies sent to Constantinople would offer immediate help. Persuading the court to fight nearer home is a greater undertaking, with its own dangers and demands upon the treasury."}),
        new Profile("Orthodox",true,new[]{"Serbia's court governs under the weight of Ottoman power. Survival has required obligations which an imperial envoy cannot wish away merely by invoking Christian brotherhood.","Shared Orthodox faith gives the embassy an opening. Breaking with the Sultan requires a political decision, with consequences for the ruler's household and people.","Discreet aid asks less of the court than an open breach with the Sultan. Your envoy must win enough confidence to make either possible, while remembering whose villages would bear the first reprisals."}),
        new Profile("Catholic court",false,new[]{"Bosnia's mountain country contains fortresses, competing households and roads along which wealth travels slowly. A royal promise must survive interests closer to home.","The court looks towards Catholic diplomacy while governing a religiously divided country. Union with Rome can strengthen your appeal without making the Bosnian treasury yours to command.","Bosnia can offer volunteers, supplies and a modest subsidy. Sustained diplomacy can prepare a separate regional commitment, hindering Ottoman reinforcement traffic through Macedonia."}),
        new Profile("Muslim",false,new[]{"The Crimean Khanate is a separate Black Sea power. It is neither the Genoese colonial network nor an Ottoman dependency in these years; speaking to its ruler is a distinct embassy.","A Muslim court need not share the Sultan's ambitions. Access, trade and the balance of power can open a conversation which a plea for Christian solidarity cannot.","Funds, provisions and access to Black Sea routes could all matter to Constantinople. An envoy must establish what the Khan hopes to gain before asking him to endanger his own position for the City's sake."}),
        new Profile("Muslim",false,new[]{"The Mamluk Sultanate commands Egypt and Syria, wealthy cities and routes connecting the Mediterranean with the lands beyond. Its court has concerns far greater than the fate of a single northern embassy.","Constantinople begins with a difficult reception here. Gifts and patient resident diplomacy offer an opening, while shared religion with Mehmed does not erase rival interests between Muslim rulers.","Money and supplies may be easier to obtain than a military commitment. An embassy must give the Sultan a reason to assist Constantinople amid the many claims upon his attention and treasury."}),
        new Profile("Orthodox",true,new[]{"The Morea is bound to Constantinople through the imperial family, but the brothers who govern it have rival ambitions and immediate dangers of their own. A dynastic connection does not make their cooperation automatic.","Its churches and ruling house share the City's Orthodox inheritance. Family loyalty, local resources and disagreements over policy all shape what can actually be sent north.","Even a small contingent and stores would be welcome in the City. Greater cooperation depends upon the brothers' willingness to settle their differences and upon what they can spare from the defence of their own lands."}),
        new Profile("Catholic",false,new[]{"Ragusa, the republic of Dubrovnik, lives by the movement of ships, silver and information. Its merchants connect the Adriatic with the Balkan interior. The city guards its own government and must not be mistaken for another Venetian possession.","Its Catholic patrician rulers conduct business among neighbours of several faiths. Their independence depends on careful accommodations with stronger powers, and their most valuable diplomatic skill is often the art of appearing unthreatening.","Your court can seek credit, provisions and access to discreet commercial networks. Ragusan merchants have good reason to preserve the City's trade, but equally good reason to avoid inviting war to their own harbour."}),
        new Profile("Catholic court",false,new[]{"The Tocco lordships hold islands along the western approaches to Greece, including Cephalonia, Zakynthos and Leucas. These small possessions give their rulers useful harbours and little room for a military mistake. They are distinct from the Venetian islands nearby.","The ruling family is Latin Catholic, while many islanders follow the Orthodox Church. An envoy must speak to a household guarding its title and to ports whose inhabitants depend on passing trade.","Raimondina Ventimiglia can arrange shelter for refugees and a household for the emperor should he enter exile. These are private agreements, opened by a resident envoy. The islands do not offer ordinary relief expeditions."}),
        new Profile("Catholic",false,new[]{"Florence is a republic whose influence travels farther than its soldiers. Merchants and bankers maintain relationships throughout Italy and beyond, while powerful families shape decisions made in the city's public councils.","The Council of Florence made the city a witness to the attempted union of the churches. Your treatment of that agreement therefore has a particular resonance, although piety does not relieve the republic of its own political calculations.","The most useful answer to your appeal is a subsidy and provisions carried through Italian ports. A resident envoy can cultivate the men able to turn sympathy into credit. A Florentine purse can sustain your defenders without promising a Florentine army in the Balkans."}),
        new Profile("Catholic",false,new[]{"Milan commands a wealthy northern Italian state, sustained by towns, workshops and the fertile country around them. Its duke must secure his own position among Italian rivals before considering a distant imperial appeal.","The court is Catholic, and an appeal to defend Constantinople can carry prestige. Yet honour competes with the demands of paid soldiers, diplomacy and the next campaign nearer home.","Your embassy asks for a modest company and a subsidy, with passage arranged through Italian ports. A trusted envoy can keep the proposal before the duke and the men who control his treasury. The duke still keeps his principal armies close to Italy."}),
        new Profile("Catholic",false,new[]{"Siena is a Tuscan republic with civic traditions, banking interests and a long rivalry with Florence. Its councils defend their independence as carefully as their merchants defend an account. The republic has a voice of its own in Italian affairs.","Catholic devotion can give Constantinople's danger a hearing, but Sienese policy is not simply a smaller copy of Florence's. Reputation, commercial connections and the cost of assistance all have their advocates.","The court can seek volunteers, money and provisions, carried east through Italian ports. A small republic must watch every purse and company it sends abroad. Your envoy may cultivate its goodwill through gifts and a continuing presence, then renew an appeal once the earlier undertaking has been settled."}),
        new Profile("Orthodox",true,new[]{"Theodoro is a small principality centred on Mangup in southwestern Crimea. Mountain strongholds and access towards the coast place it among the competing interests of the Crimean Khanate and the Genoese settlements. It is a separate power from both.","Its Orthodox court shares a language of religious allegiance with Constantinople, while local survival requires dealings with Muslim and Latin neighbours. Church Union may trouble that sympathy without erasing every reason to cooperate.","A modest contingent of soldiers and provisions could make a useful answer to your appeal. The court must weigh its sympathy for Constantinople against the dangers surrounding its own mountain strongholds."}),
    };
    public static string Article(int index) {
        return string.Join("\n\n",All[index].Paragraphs);
    }
}
